import boto3
from datetime import datetime, timedelta

def compare_cloudwatch_metrics(
    instance_id_1: str,
    instance_id_2: str,
    metric_name: str = "CPUUtilization",
    namespace: str = "AWS/EC2",
    period: int = 300, # seconds (e.g., 5 minutes)
    stat: str = "Average",
    duration_minutes: int = 60,
    region_name: str = "us-east-1"
) -> dict:
    """
    Compares a specific CloudWatch metric for two different resources (e.g., EC2 instances)
    over the same time window.

    Args:
        instance_id_1: The ID of the first resource (e.g., EC2 instance).
        instance_id_2: The ID of the second resource (e.g., EC2 instance).
        metric_name: The name of the metric to compare (e.g., 'CPUUtilization').
        namespace: The namespace of the metric (e.g., 'AWS/EC2').
        period: The granularity of the returned data, in seconds (e.g., 300 for 5 minutes).
        stat: The statistic to retrieve (e.g., 'Average', 'Sum', 'Maximum', 'Minimum', 'SampleCount').
        duration_minutes: The duration of the time window to query, in minutes.
        region_name: The AWS region to connect to.

    Returns:
        A dictionary containing the metric data for both instances, or an error message.
    """
    client = boto3.client("cloudwatch", region_name=region_name)

    end_time = datetime.utcnow()
    start_time = end_time - timedelta(minutes=duration_minutes)

    metric_data_queries = [
        {
            'Id': 'm1',
            'MetricStat': {
                'Metric': {
                    'Namespace': namespace,
                    'MetricName': metric_name,
                    'Dimensions': [
                        {'Name': 'InstanceId', 'Value': instance_id_1}
                    ]
                },
                'Period': period,
                'Stat': stat,
            },
            'ReturnData': True,
        },
        {
            'Id': 'm2',
            'MetricStat': {
                'Metric': {
                    'Namespace': namespace,
                    'MetricName': metric_name,
                    'Dimensions': [
                        {'Name': 'InstanceId', 'Value': instance_id_2}
                    ]
                },
                'Period': period,
                'Stat': stat,
            },
            'ReturnData': True,
        }
    ]

    try:
        response = client.get_metric_data(
            MetricDataQueries=metric_data_queries,
            StartTime=start_time,
            EndTime=end_time,
            ScanBy='TimestampAscending'
        )

        results = {
            'instance_1_data': [],
            'instance_2_data': []
        }

        for result in response.get('MetricDataResults', []):
            if result['Id'] == 'm1':
                for i in range(len(result['Timestamps'])):
                    results['instance_1_data'].append({
                        'timestamp': result['Timestamps'][i].isoformat(),
                        'value': result['Values'][i]
                    })
            elif result['Id'] == 'm2':
                for i in range(len(result['Timestamps'])):
                    results['instance_2_data'].append({
                        'timestamp': result['Timestamps'][i].isoformat(),
                        'value': result['Values'][i]
                    })

        return results

    except Exception as e:
        return {"error": str(e)}
